def _collect_methods_and_accessors(node: ast.ClassDef) -> tuple[list[str], list[str]]:
    methods, accessors = [], []
    for item in node.body:
        if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)) and is_public(item.name) and not is_overload_stub(item):
            if item.name not in methods:
                methods.append(item.name)
            if _is_accessor(item) and item.name not in accessors:
                accessors.append(item.name)
    return methods, accessors

def _collect_class_attributes(node: ast.ClassDef) -> set[str]:
    attrs: set[str] = set()
    # first pass: assignments and __slots__
    for item in node.body:
        if isinstance(item, ast.Assign):
            attrs.update(t.id for t in item.targets if isinstance(t, ast.Name) and is_public(t.id))
        elif isinstance(item, ast.AnnAssign) and isinstance(item.target, ast.Name) and is_public(item.target.id):
            attrs.add(item.target.id)
        # __slots__ handling (same logic as original)
        if isinstance(item, (ast.Assign, ast.AnnAssign)):
            targets = item.targets if isinstance(item, ast.Assign) else [item.target]
            if any(isinstance(x, ast.Name) and x.id == "__slots__" for x in targets):
                for el in getattr(item.value, "elts", []):
                    if isinstance(el, ast.Constant) and isinstance(el.value, str) and is_public(el.value):
                        attrs.add(el.value)
    # second pass: attribute writes inside methods
    for item in node.body:
        if not isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        receiver = self_parameter(item)
        if receiver is None:
            continue
        for child in walk_receiver_scope(item, receiver):
            if (
                isinstance(child, ast.Attribute)
                and isinstance(child.value, ast.Name)
                and child.value.id == receiver
                and isinstance(child.ctx, ast.Store)
                and is_public(child.attr)
            ):
                attrs.add(child.attr)
    return attrs
```
